import { randomBytes } from 'node:crypto';

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/** Short, unambiguous, URL-safe token. */
export function randomToken(length = 10): string {
  const bytes = randomBytes(length);
  let out = '';
  for (let i = 0; i < length; i += 1) {
    out += ALPHABET[bytes[i] % ALPHABET.length];
  }
  return out;
}

/**
 * Payment references are generated by us (never by the gateway) so a record
 * always exists before the subscriber is sent to checkout.
 * Shape: PTX-<telegramId>-<base36 time>-<random>
 */
export function buildPaymentReference(telegramId: number): string {
  return `PTX-${telegramId}-${Date.now().toString(36).toUpperCase()}-${randomToken(6)}`;
}
